namespace optiling {
static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    CrossModalAttentionCustomTilingData tiling;

    // Expect input shapes:
    // q: [B, H, Tq, Dh]
    // kv: [B, H, Tk, Dh]
    const gert::Shape* qShape = context->GetInputShape(0);
    const gert::Shape* kvShape = context->GetInputShape(1);

    if (qShape->GetDimNum() != 4 || kvShape->GetDimNum() != 4) {
        return ge::GRAPH_PARAM_INVALID;
    }

    uint32_t B  = static_cast<uint32_t>(qShape->GetDim(0));
    uint32_t H  = static_cast<uint32_t>(qShape->GetDim(1));
    uint32_t Tq = static_cast<uint32_t>(qShape->GetDim(2));
    uint32_t Dh = static_cast<uint32_t>(qShape->GetDim(3));
    uint32_t Tk = static_cast<uint32_t>(kvShape->GetDim(2));

    uint32_t groups = B * H;
    uint32_t blockDim = std::min<uint32_t>(groups, 32);

    tiling.set_batch(B);
    tiling.set_heads(H);
    tiling.set_lenQ(Tq);
    tiling.set_lenK(Tk);
    tiling.set_headDim(Dh);
    tiling.set_blockDim(blockDim);

    context->SetBlockDim(blockDim);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0; // no extra workspace
    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // out has same shape as q: [B, H, Tq, Dh]
    const gert::Shape* qShape = context->GetInputShape(0);
    gert::Shape* outShape = context->GetOutputShape(0);
    *outShape = *qShape;
    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    const auto inputDataType = context->GetInputDataType(0);
    context->SetOutputDataType(0, inputDataType);
    return ge::GRAPH_SUCCESS;
}
